with base as (select *, add_months(ends_on, 6) as ends_on_plus_months, coalesce(channel, 'N/A') as channel_clean from promotions where starts_on > date '2023-12-22' and year(starts_on) = 2023) select case when discount_pct >= 0.28 then 'LARGE' else 'SMALL' end as discount_pct_tier, count(*) as row_count, count(case when channel = 'store' then 1 end) as store_count, round(sum(discount_pct) / nullif(count(case when channel = 'web' then 1 end), 0), 2) as discount_pct_per_web from base group by case when discount_pct >= 0.28 then 'LARGE' else 'SMALL' end;
